insert into public.process_stages (segment, id, "order", title, short_description, owner, participants, sla, content, checklist, warnings, template_ids, module_ids) values ('sm', 'recebimento', 1, 'Recebimento do projeto', 'Entenda como o projeto chega até o time de Projetos e o que precisa ser verificado.', 'consultor', '{}', '2 dias úteis', ARRAY['O HubSpot é o CRM da empresa onde as informações ficam centralizadas e são repassadas entre os times. Quando o time de vendas finaliza uma venda, cria-se um ticket no HubSpot para que o cliente chegue ao time de implantação como um projeto vendido. O gestor da área é notificado e atribui o projeto a um consultor e a um gerente de projetos.','Somos notificados do início do projeto de duas formas: atribuição no ticket do HubSpot, e e-mail enviado pela gestão nos apresentando ao cliente.']::text[], ARRAY['Verificar a atribuição do projeto no ticket do HubSpot','Responder o e-mail de apresentação dentro do SLA']::text[], '{}', '{}', '{}');
insert into public.process_stages (segment, id, "order", title, short_description, owner, participants, sla, content, checklist, warnings, template_ids, module_ids) values ('sm', 'analise-projeto', 2, 'Análise do projeto', 'Confira a proposta comercial e o histórico da venda antes do primeiro contato.', 'consultor', ARRAY['vendas']::text[], NULL, ARRAY['Proposta: analisar os módulos contratados (checar o check amarelo, exceto mobilidade — normalmente vem zerado na proposta); analisar as formas de pagamento do Travel; analisar se veio prazo de vigência na proposta.','HubSpot: verificar as propriedades preenchidas pelo vendas para entender o objetivo do cliente, e as observações do card para ver se o vendas deixou alguma informação relevante para a condução do projeto.','Repasse de vendas: reunião com o vendedor, para entender o histórico de venda do projeto.']::text[], ARRAY['Analisar os módulos contratados','Verificar formas de pagamento (Travel)','Analisar prazo de vigência','Verificar propriedades do HubSpot','Ler observações do card','Realizar repasse de vendas com o vendedor']::text[], ARRAY['Em caso de divergência na proposta, seguir o processo de devolutiva comercial formalizado.']::text[], '{}', '{}');
insert into public.process_stages (segment, id, "order", title, short_description, owner, participants, sla, content, checklist, warnings, template_ids, module_ids) values ('sm', 'primeiro-contato', 3, 'Primeiro contato', 'Responda o cliente e solicite os requisitos de cada módulo contratado.', 'consultor', ARRAY['cliente']::text[], NULL, ARRAY['Responder em cima do e-mail da coordenação, com o template "1. Template - Etapas de projeto SM - primeiro contato", sugerindo a agenda de kick off.','Solicitar os requisitos de cada módulo contratado com os e-mails padrão correspondentes.']::text[], '{}', '{}', ARRAY['tpl-primeiro-contato-sm','tpl-cargas-expense','tpl-requisitos-travel','tpl-implantacao-vcn','tpl-implantacao-cartao','tpl-carteira-digital']::text[], ARRAY['expense','travel','vcn','cartao-paytrack','carteira-digital']::text[]);
insert into public.process_stages (segment, id, "order", title, short_description, owner, participants, sla, content, checklist, warnings, template_ids, module_ids) values ('sm', 'preparacao-interna', 4, 'Preparação interna', 'Monte o cronograma, a pasta do cliente e organize o HubSpot antes da primeira reunião.', 'consultor', ARRAY['gp','coordenacao']::text[], NULL, ARRAY['Criar o cronograma no Smartsheet assim que conseguir agendar o kick off.','Criar uma pasta para o cliente no Drive (na pasta de projetos), onde devem ser armazenadas todas as cargas, documentações e o escopo do projeto.','Mover o card no HubSpot para "Em andamento" após a reunião de kick off.']::text[], ARRAY['Time do projeto: preencher coordenador, consultor e GP','ID do HubSpot: obrigatório — é o que faz rodar a integração Smartsheet ↔ HubSpot','Potencial travel: preencher com o volume de viagens do HubSpot (campo "[TRVL] Soma de todos os potenciais de volume travel"); se vazio, preencher com zero e mapear o volume com o cliente depois','BU: conforme a segmentação do cliente no HubSpot — usado nos filtros do BI da gestão','Variância: ao criar um cronograma novo a partir do modelo, redefinir as "Referências iniciais" para não constar como atrasado','Tipo de projeto: Novo / Novo - Integração segunda onda / Base / Base - Segunda onda','Criar a pasta do cliente no Drive']::text[], ARRAY['O potencial travel é de suma importância para o time de viagens entender se precisa efetuar novas contratações.']::text[], '{}', '{}');
insert into public.process_stages (segment, id, "order", title, short_description, owner, participants, sla, content, checklist, warnings, template_ids, module_ids) values ('sm', 'kick-off', 5, 'Kick-off', 'Conduza a reunião de abertura do projeto, com ou sem integração.', 'consultor', ARRAY['cliente']::text[], NULL, ARRAY['Kick off com ou sem integração, conforme o escopo contratado.','Formalizar a reunião com o e-mail "2. Template Etapa 1 - Formalização - Kick-off".']::text[], '{}', '{}', ARRAY['tpl-kickoff-formalizacao']::text[], '{}');
insert into public.process_stages (segment, id, "order", title, short_description, owner, participants, sla, content, checklist, warnings, template_ids, module_ids) values ('sm', 'definicao-escopo', 6, 'Definição de escopo', 'Registre o escopo acordado e obtenha o aceite do cliente.', 'consultor', ARRAY['cliente']::text[], NULL, ARRAY['Registrar todo o escopo no Termo de escopo e disponibilizá-lo para aceite na base de produção do cliente.','Enviar o e-mail "3. Template - Envio do Termo de escopo".']::text[], '{}', ARRAY['O aceite do escopo é obrigatório para seguir com a parametrização da base.']::text[], ARRAY['tpl-termo-escopo']::text[], '{}');
insert into public.process_stages (segment, id, "order", title, short_description, owner, participants, sla, content, checklist, warnings, template_ids, module_ids) values ('sm', 'parametrizacao', 7, 'Parametrização', 'Configure a base de acordo com o escopo aceito pelo cliente.', 'consultor', '{}', NULL, ARRAY['Parametrização da base conforme o escopo aceito pelo cliente.']::text[], '{}', '{}', '{}', '{}');
