insert into public.process_stages (segment, id, "order", title, short_description, owner, participants, sla, content, checklist, warnings, template_ids, module_ids) values ('sm', 'homologacao-assistida', 9, 'Homologação assistida', 'Libere o acesso para o cliente testar a base.', 'consultor', ARRAY['cliente']::text[], NULL, ARRAY['Liberar o acesso à base para o cliente efetuar os testes.','E-mail para liberar o acesso: "4. Template Etapa 3 - Homologação".']::text[], '{}', '{}', ARRAY['tpl-homologacao']::text[], '{}');
insert into public.process_stages (segment, id, "order", title, short_description, owner, participants, sla, content, checklist, warnings, template_ids, module_ids) values ('sm', 'retorno-testes', 10, 'Retorno dos testes', 'Receba e trate o retorno dos testes realizados pelo cliente.', 'cliente', ARRAY['consultor']::text[], NULL, ARRAY['Retorno dos testes realizados pelo cliente na base homologada.']::text[], '{}', '{}', '{}', '{}');
insert into public.process_stages (segment, id, "order", title, short_description, owner, participants, sla, content, checklist, warnings, template_ids, module_ids) values ('sm', 'aceite-homologacao', 11, 'Aceite da homologação', 'Obtenha o aceite formal do Termo de homologação.', 'consultor', ARRAY['cliente']::text[], NULL, ARRAY['O aceite do Termo de homologação é obrigatório para o go live do projeto.','E-mail a ser enviado: "2. Template Etapa 3 - Aceite da Homologação".']::text[], '{}', ARRAY['O aceite é obrigatório para o go live do projeto.']::text[], ARRAY['tpl-aceite-homologacao']::text[], '{}');
insert into public.process_stages (segment, id, "order", title, short_description, owner, participants, sla, content, checklist, warnings, template_ids, module_ids) values ('sm', 'treinamento-adm', 12, 'Treinamento de administrador', 'Treine o administrador da ferramenta no cliente.', 'consultor', ARRAY['cliente']::text[], NULL, ARRAY['Treinamento de administrador.','E-mail: "4.1 Template Etapa 3 - Homologação (Treinamento ADM)".']::text[], '{}', '{}', ARRAY['tpl-treinamento-adm']::text[], '{}');
