insert into public.process_stages (segment, id, "order", title, short_description, owner, participants, sla, content, checklist, warnings, template_ids, module_ids) values ('sm', 'go-live', 14, 'Go live', 'Formalize a entrada em produção do projeto.', 'gp', ARRAY['consultor','cliente']::text[], NULL, ARRAY['O go live é formalizado pelo GP, com o e-mail "5. Template etapa 4 - Go live".']::text[], '{}', '{}', ARRAY['tpl-go-live']::text[], '{}');
insert into public.process_stages (segment, id, "order", title, short_description, owner, participants, sla, content, checklist, warnings, template_ids, module_ids) values ('le', 'recebimento', 1, 'Recebimento do projeto', 'O GP é notificado do início do projeto e responde ao cliente.', 'gp', '{}', '2 dias úteis', ARRAY['Somos notificados do início do projeto de duas formas: atribuição no ticket do HubSpot, e e-mail enviado pela gestão nos apresentando ao cliente.','No LE, é o GP quem responde o e-mail de apresentação dentro do SLA — diferente do SM, onde o consultor responde.']::text[], ARRAY['Verificar a atribuição do projeto no ticket do HubSpot','Responder o e-mail de apresentação dentro do SLA ("Boas Vindas - Projetos LE")']::text[], '{}', ARRAY['tpl-boas-vindas-le']::text[], '{}');
