insert into public.process_stages (segment, id, "order", title, short_description, owner, participants, sla, content, checklist, warnings, template_ids, module_ids) values ('le', 'kick-off', 6, 'Kick-off', 'O GP conduz a reunião de abertura do projeto com o cliente.', 'gp', ARRAY['cliente','consultor']::text[], NULL, ARRAY['O GP conduz o kick off com o cliente.','Formalizar com o e-mail "Formalização do Kick Off - Projetos LE" (também referenciado como "2. Template Etapa 1 - Formalização - Kick-off" no fluxo padrão).']::text[], '{}', '{}', ARRAY['tpl-kickoff-le','tpl-kickoff-formalizacao']::text[], '{}');
insert into public.process_stages (segment, id, "order", title, short_description, owner, participants, sla, content, checklist, warnings, template_ids, module_ids) values ('le', 'handoff-consultor', 7, 'Handoff para o consultor', 'A condução do projeto passa do GP para o consultor.', 'gp', ARRAY['consultor','cliente']::text[], NULL, ARRAY['Após a execução do kick off, o GP sinaliza ao consultor para que ele possa agendar a definição de escopo com o cliente e solicitar as cargas.','O consultor deve responder o e-mail no qual o GP apresenta o consultor ("Apresentação do Consultor LE"), propondo a agenda de definição de escopo.','Solicitar os requisitos de cada módulo contratado com os e-mails padrão correspondentes.','Criar uma pasta para o cliente no Drive, na pasta "Projetos L/E", onde devem ser armazenadas todas as cargas e documentações.']::text[], '{}', '{}', ARRAY['tpl-apresentacao-consultor-le','tpl-cargas-expense','tpl-requisitos-travel','tpl-implantacao-vcn','tpl-implantacao-cartao','tpl-carteira-digital']::text[], ARRAY['expense','travel','vcn','cartao-paytrack','carteira-digital']::text[]);
insert into public.process_stages (segment, id, "order", title, short_description, owner, participants, sla, content, checklist, warnings, template_ids, module_ids) values ('le', 'definicao-escopo', 8, 'Definição de escopo', 'O consultor registra o escopo e obtém o aceite do cliente.', 'consultor', ARRAY['cliente']::text[], NULL, ARRAY['O consultor registra todo o escopo no Termo de escopo e o disponibiliza para aceite na base de produção do cliente.','E-mail a ser enviado ao cliente: "3. Template - Envio do Termo de escopo".']::text[], '{}', ARRAY['O aceite do escopo é obrigatório para seguir com a parametrização da base.']::text[], ARRAY['tpl-termo-escopo']::text[], '{}');
