insert into public.process_modules (id, title, content, template_ids) values ('expense', 'Expense', ARRAY['Solicitar as cargas iniciais do cliente com o e-mail padrão de solicitação de cargas.']::text[], ARRAY['tpl-cargas-expense']::text[]);
insert into public.process_modules (id, title, content, template_ids) values ('travel', 'Travel', ARRAY['Solicitar os requisitos com o e-mail padrão de implantação do Travel Tech.','No SM, o formulário de requisitos é enviado pelo HubSpot: selecionar o contato e preencher o "Papel do contato" (ex.: responsável pela implantação) e a "Data para disparo da pesquisa".','Se o projeto tiver Travel, é obrigatório manter uma observação atualizada no HubSpot com o status de: Contrato (enviado/assinado), Aditivo (se o cliente usa cartão de crédito — foto recebida e aditivo assinado), Forma de pagamento (por serviço) e Locação (se utiliza e como está o acordo tripartite).']::text[], ARRAY['tpl-requisitos-travel']::text[]);
insert into public.process_modules (id, title, content, template_ids) values ('vcn', 'VCN', ARRAY['Solicitar os requisitos com o e-mail padrão "Passo 1. Implantação VCN".']::text[], ARRAY['tpl-implantacao-vcn']::text[]);
insert into public.process_modules (id, title, content, template_ids) values ('cartao-paytrack', 'Cartão Paytrack', ARRAY['Solicitar os requisitos com o e-mail padrão de implantação do Paytrack Card.']::text[], ARRAY['tpl-implantacao-cartao']::text[]);
insert into public.process_modules (id, title, content, template_ids) values ('carteira-digital', 'Carteira Digital', ARRAY['Solicitar os documentos necessários com o e-mail padrão de solicitação de documentos da Carteira Digital.']::text[], ARRAY['tpl-carteira-digital']::text[]);
insert into public.process_modules (id, title, content, template_ids) values ('conciliacao', 'Conciliação', ARRAY['Módulo de conciliação, implantado seguindo o processo padrão do serviço contratado.']::text[], '{}');
insert into public.process_modules (id, title, content, template_ids) values ('integracoes', 'Integrações', ARRAY['Tipos de condução documentados: projeto novo com integração em primeira onda; projeto novo com integração em segunda onda; projeto de base.','Etapas internas: sprint, cronograma, reunião de briefing/alinhamento, reunião de escopo, levantamento de requisitos técnicos e alocação na sprint.']::text[], '{}');
