-- Central de Implantação content (SM/LE stages, e-mail templates, modules), moved from
-- the static web/src/data/*.ts files into Supabase so the admin screen can edit them
-- without a redeploy. RLS is enabled with no policies: only server-side code using the
-- secret (service_role) key can read/write — the browser never touches this directly.

create table if not exists public.process_stages (
  segment text not null check (segment in ('sm', 'le')),
  id text not null,
  "order" int not null,
  title text not null,
  short_description text not null default '',
  owner text not null check (owner in ('consultor', 'gp', 'cliente', 'vendas', 'coordenacao')),
  participants text[] not null default '{}',
  sla text,
  content text[] not null default '{}',
  checklist text[] not null default '{}',
  warnings text[] not null default '{}',
  template_ids text[] not null default '{}',
  module_ids text[] not null default '{}',
  updated_at timestamptz not null default now(),
  primary key (segment, id)
);
alter table public.process_stages enable row level security;

create table if not exists public.process_templates (
  id text primary key,
  title text not null,
  url text,
  updated_at timestamptz not null default now()
);
alter table public.process_templates enable row level security;

create table if not exists public.process_modules (
  id text primary key,
  title text not null,
  content text[] not null default '{}',
  template_ids text[] not null default '{}',
  updated_at timestamptz not null default now()
);
alter table public.process_modules enable row level security;

-- set_updated_at() already exists from the profiles/review_sessions migration.
drop trigger if exists process_stages_set_updated_at on public.process_stages;
create trigger process_stages_set_updated_at before update on public.process_stages for each row execute function public.set_updated_at();
drop trigger if exists process_templates_set_updated_at on public.process_templates;
create trigger process_templates_set_updated_at before update on public.process_templates for each row execute function public.set_updated_at();
drop trigger if exists process_modules_set_updated_at on public.process_modules;
create trigger process_modules_set_updated_at before update on public.process_modules for each row execute function public.set_updated_at();

